from pathlib import Path
import json
root=Path(__file__).resolve().parents[1]
roles={
 'data-engineer':('Data ingestion and persistence','Own data decoding, validation, schemas, versioning, transactional persistence, rollback and recovery. Build invalid-input tests. Never assume the first dataset is the only dataset. Report assumptions and evidence.'),
 'optimization-engineer':('Optimization and operations research','Own objective, constraints, algorithm choices, deterministic reruns and performance baselines. Distinguish mandatory invariants from soft goals. Use input times/durations as specified. Do not invent authoritative external facts.'),
 'frontend-engineer':('Frontend, dashboard and information design','Own user journeys, frontend states, dashboards, charts, accessibility, layout and error states. Apply Impeccable if installed. Check controls actually work. Do not use Computer Use or automated browser interaction in proctored environment.'),
 'verification-engineer':('Independent acceptance verification','Read requirements, create an independent checker for hard invariants, adversarial tests, security boundaries, persistence and reproducibility. Never certify a feature from screenshots or build success alone. Do not spawn other agents.'),
 'ml-engineer':('Prediction and statistical modeling','Own reproducible baseline, splits, missingness, leakage prevention, error metrics, interval/sensitivity where valid. Separate estimated future quantities from observed facts. Avoid tuning to test data.'),
 'backend-engineer':('Backend/API/auth architecture','Own API contracts, server-side authn/authz, validation, database integration, healthchecks and runtime. Use local resources. Verify failure paths and transaction atomicity. Do not spawn other agents.'),
 'tooling-engineer':('Tool/MCP integration and agent workflow','Own local tool contracts, orchestration, idempotence, bounded retries, failure recovery and visibility. No external model/API connection unless expressly authorized. Do not spawn other agents.'),
 'document-engineer':('Document parsing and reports','Own input parsing, extraction evidence, output format and layout verification. Attribute numbers to actual inputs; surface ambiguous scans or OCR uncertainty. No task-content external uploads.'),
 'algorithm-engineer':('Algorithm design and complexity','Own exact or approximate algorithms, complexity and correctness proofs for available constraints. Compare with brute force oracles on small test domains and benchmark stress cases.'),
 'simulation-engineer':('Simulation and sensitivity analysis','Own scenario engine, sampling assumptions, seed, model calibration, sensitivity and uncertainty. Label observed vs modeled variables and discuss decision impact.'),
 'security-engineer':('Security review for local system','Own threat model, privilege boundaries, input validation, safe defaults, secret handling and regression tests. No external security scan, exfiltration or prohibited system access.'),
}
for name,(desc,body) in roles.items():
  effort='high' if name in ('optimization-engineer','ml-engineer','verification-engineer','security-engineer','algorithm-engineer') else 'medium'
  instructions=(f"You are the {name} subagent in a time-boxed hackathon. {body} Work only on explicitly assigned files; negotiate shared contracts with main before edits. Assume main+3 is the TOTAL agent limit: never spawn a subagent or parallel reviewer. Read the actual task and do not infer missing requirements from previous examples. Send main concise updates with: files changed; executable evidence and commands; decision and alternatives; assumptions/unanswered questions; known risks; entries to add to DECISION_LOG.md and EXPLAINABILITY_NOTES.md. Never fabricate tests, metrics, sources, interviews or human actions. Use the provided Codex model and local tools; never external AI, prohibited automation, Git Push, or task-data outbound communication.")
  # toml quoted triple multiline no user-specific data
  content=f'name = "{name}"\ndescription = "{desc}"\nmodel_reasoning_effort = "{effort}"\ndeveloper_instructions = """\n{instructions}\n"""\n'
  (root/'agent_roles'/f'{name}.toml').write_text(content,encoding='utf-8')
skills={
'decision-journal':('Use whenever choosing an architecture, objective, threshold, validation rule, model, fallback, shortcut or significant tradeoff during a timed engineering task.', '''# Decision journal discipline\n\nBefore implementing a nontrivial decision, add a short entry to `DECISION_LOG.md` using the template. Record: **decision, real objective, requirement/evidence, alternatives, rationale, measurable tradeoffs, uncertainty, validation, fallback, owner, timestamp and status**. Do not backfill guessed motives or claim user assent.\n\nUse `EXPLAINABILITY_NOTES.md` as a separate concise human-facing account: Why this solution? Why this data treatment? Why this metric? What can go wrong and how recover? What did the operator actually confirm? Keep factual origin tags `TASK`, `DATA`, `STAKEHOLDER`, `ENGINEERING_ASSUMPTION`, `TEST`. Include rejected alternatives.\n\nWhen changing an earlier choice, mark it `superseded`; never silently rewrite history. Log only meaningful decisions to avoid wasting time. At checkpoints (initial contract, first working vertical slice, integration, handoff) make main consolidate the journal and ask user about any critical ambiguous assumption using platform-approved communication.\n\n**Do not use AI for restricted post-submission written responses.** These records are preparation material for the participant's own understanding before submission, not text to paste into a restricted assessment.\n'''),
'data-quality':('Use for CSV, Excel, databases, ingestion, schema validation, temporal joins, deduplication, missing values, reference integrity and dataset switching.', '''# Data trust gate\n\nBuild a data contract from real inputs: file presence, schema types, nullability, unique keys, foreign keys, domain constraints, units, time zones, date grain and bidirectional relations where relevant. Inspect data before asserting distributions. Report invalid rows with actionable diagnostics.\n\nSeparate **validation** from **activation**. A rejected dataset must not mutate active state. Use atomic persistence and regression-test partial failures, out-of-date plans, restart consistency and version mismatch.\n\nFor ML data: detect leakage, point-in-time joins, time-dependent groups and skew; no random split where time-order matters. Never replace all actual users with historic utilization unless explicitly allowed.\n\nCapture the evidence and limitations in `DECISION_LOG.md`. Never send files, rows, metadata or user-supplied prompts to external tools.\n'''),
'model-evaluation':('Use for predictions, classification, forecasting, simulations, ranking models, uncertainty, scenarios, feature selection or metric justification.', '''# Evaluation before claims\n\n1. State target and what is actually being predicted; specify horizon, unit, labels and allowed features.\n2. Choose a transparent baseline first. Explain why MAE, RMSE, MAPE, log loss, F1, accuracy, calibration or another metric matches business cost. Avoid metrics invalid for zero/rare events.\n3. Freeze a valid split (time-based, group-based or temporal holdout as appropriate). Check target leakage and label availability.\n4. Train/compare only after recording settings and seed. Evaluate on held-out data.\n5. Show errors by meaningful slice; check operational constraints and sensitivity, not only aggregate score.\n6. Distinguish model forecast from actual measured value; communicate uncertainty honestly.\n7. Document why this algorithm/threshold was selected, what alternatives were ruled out and what would invalidate it.\n\nNever invent benchmark improvement or metrics not calculated from current task data.\n'''),
'optimization-audit':('Use for route planning, allocation, scheduling, logistics, constraints, objective functions, heuristics or numerical optimization.', '''# Optimization design & audit\n\nClassify constraints into **hard** (must always hold) and **soft** (optimization tradeoffs). Examples: capacities, exact assignment, allowed nodes, time windows, forbidden combinations vs travel time, distance, wait, fairness and resource count. The exact constraints come from the task; examples are not specifications.\n\nExplicitly write objective vector and scalarization if used, weight and unit interpretation; consider lexicographic constraints before arbitrary weighted sums. Compare against a trivial feasible baseline. Preserve reproducibility; tie-breaking must be deterministic.\n\nIndependently recalculate from original input for every generated result: all required assignments, no prohibited assignment, resource capacity at every interval, start/end windows, direction-sensitive edge weights, date and time boundary behavior, and reproducibility. Check feasibility before calling result optimized.\n\nMeasure objective, feasible rate, runtime and tradeoffs; never label a heuristic globally optimal without proof. Log stakeholder-verified rules separately from engineering assumptions.\n'''),
'interface-contract':('Use when multiple agents implement frontend/backend/data tool boundaries, API contracts, schema versions, role-based permissions or authentication.', '''# Contract-first parallel delivery\n\nBefore delegating: main defines minimal shared schema/API/endpoints, ownership of each file/folder, error format and state/version semantics. Subagents do not edit the same files concurrently. Main owns shared contract changes and integration.\n\nBackend enforces authorization. Frontend hiding buttons is not access control. Test invalid ID, invalid role, stale data, malformed payload, partial persistence, restart, and mismatch between generated results and active input version.\n\nFor UX: no fake success on failed responses, no stale results presented as new, a distinguishable loading/error/empty state, and keyboard-accessible important controls.\n\nEvery changed contract requires notifying affected agents and updating acceptance matrix.\n'''),
'independent-verification':('Use for final acceptance, complicated invariants, edge cases, regression, model correctness, API authorization or offline local test generation.', '''# Independent verification\n\nCreate `VERIFICATION_MATRIX.md` by mapping **every mandatory requirement** to location, test/check command, observed result and status (verified/failed/unverified). Avoid a self-referential checker that copies the production algorithm. For numerical output, compare to small brute-force cases or independently recomputed constraints.\n\nTest happy path, adversarial input, broken references, failed DB writes, process restart, time zones/date rollovers, multi-user authorization and stale UI states as applicable. Keep objective tests separate from visual/manual checks.\n\nDo not claim tests were run when they were not; if browser auto-operation is prohibited, manually inspect in provided preview and mark programmatic UI testing not performed. In the final 10 minutes prioritize mandatory output/schema validation and submission file existence.\n'''),
'submission-gate':('Use near a deadline to verify required deliverables, launcher instructions, environment file safety, code paths, test evidence and source confidentiality.', '''# Final submission gate\n\nRead the actual task artifact list before judging completeness. Preserve provided task/README files unchanged. Validate required filenames/paths, no secrets or external credentials, no forbidden output, no missing startup instructions, and no untracked required files. Check reproducible launch from fresh DB/environment, health endpoint and Dockerfile if required.\n\nIf a human-only written test follows, stop ALL AI usage at the boundary and require the participant to type personal answers. Before that phase, summarize architecture/decisions, evidence and limitations in `EXPLAINABILITY_NOTES.md` but never fabricate the human's actions or claim future exam compliance.\n\nNo Git Push or external task artifact upload. Do not run Computer Use, browser automation, screen automation, or prohibited monitoring bypass.\n'''),
}
for name,(desc,body) in skills.items():
  d=root/'skills'/name
  d.mkdir(parents=True,exist_ok=True)
  (d/'SKILL.md').write_text(f'---\nname: {name}\ndescription: {desc}\n---\n\n{body}',encoding='utf-8')
print('Wrote',len(roles),'agent roles and',len(skills),'skills')
